#!/bin/bash
# Usage: website.sh [CORE]. Regenerates the CPU timings of prng.di.unimi.it: times
# the generators of the tables of the website (main, fp, and vect of gens.tsv)
# with go.sh on CORE (default 8), and writes the summary of summarize.py into
# website.txt. It takes less than half an hour on an AMD EPYC 9R45: run it under
# nohup. The GPU table of the website is regenerated by gpu/compile-gpu.sh,
# gpu/test-gpu.sh, and gpu/summarize-gpu.py, on a machine with an NVIDIA GPU.
cd "$(dirname "$0")"
bash go.sh "${1:-8}" main fp vect || exit 1
python3 summarize.py > website.txt
